#!/usr/bin/env bash
# ASI3: Qwen3.6-27B LoRA SFT on questions_and_code.jsonl, 1 epoch, 8 NPUs.
set -euo pipefail

REMOTE_ROOT="/root/work/quantum-gpt"
MODEL_PATH="/root/work/filestorage/Qwen3.8-27B"
DATA_DIR="data/generated/quantum_dedup_1k_glm52_soft_distill_v3"
TRAIN_FILE="$REMOTE_ROOT/$DATA_DIR/train_sft_questions_code.jsonl"
EVAL_FILE="$REMOTE_ROOT/$DATA_DIR/eval_sft_questions_code.jsonl"

RUN_ID="27b-sft-questions-code-$(date -u +%Y%m%dT%H%M%SZ)"
OUTPUT_DIR="$REMOTE_ROOT/outputs/qg-27b-sft-questions-code-$RUN_ID"
LOG_PATH="$REMOTE_ROOT/logs/qg-27b-sft-questions-code-$RUN_ID.log"

mkdir -p "$(dirname "$LOG_PATH")" "$OUTPUT_DIR" "$REMOTE_ROOT/$DATA_DIR"

# Write training data from embedded base64
echo "Writing train data..."
echo "" | base64 -d > "$TRAIN_FILE"
echo "Writing eval data..."
echo "" | base64 -d > "$EVAL_FILE"

echo "Train: $(wc -l < "$TRAIN_FILE") rows"
echo "Eval:  $(wc -l < "$EVAL_FILE") rows"

export PYTORCH_NPU_ALLOC_CONF="expandable_segments:True"
export ASCEND_LAUNCH_BLOCKING=0
export QWEN_SFT_GRADIENT_CHECKPOINTING_REENTRANT=0
export PYTHONUNBUFFERED=1

echo "__TRAINING_START__ model=$MODEL_PATH train=$TRAIN_FILE eval=$EVAL_FILE out=$OUTPUT_DIR"

nohup torchrun --nproc_per_node=8 training/qwen_sft_peft.py \
  --model-name "$MODEL_PATH" \
  --train-file "$TRAIN_FILE" \
  --eval-file "$EVAL_FILE" \
  --output-dir "$OUTPUT_DIR" \
  --max-length 2048 \
  --num-epochs 1 \
  --per-device-batch-size 1 \
  --gradient-accumulation-steps 4 \
  --learning-rate 2e-5 \
  --lora-rank 16 \
  --lora-alpha 32 \
  --lora-dropout 0.0 \
  --target-modules q_proj k_proj v_proj o_proj gate_proj up_proj down_proj \
  --train-on-completions-only \
  --gradient-checkpointing \
  --train-layernorm \
  --max-trainable-parameters 5000000 \
  --max-trainable-parameters 2000000000 \
  --checkpoint-interval-seconds 900 \
  > "$LOG_PATH" 2>&1 &
PID=$!
echo "$PID" > "$OUTPUT_DIR/asi3_27b_sft.pid"
echo "__LAUNCHED__ pid=$PID log=$LOG_PATH out=$OUTPUT_DIR"
sleep 5
ps -p "$PID" -o pid,stat,etime,cmd 2>/dev/null || echo "PROCESS_NOT_FOUND"
echo "--- log tail ---"; tail -n 20 "$LOG_PATH" 2>/dev/null || true
echo "Monitor: tail -f $LOG_PATH"
